class Solution {
public:
    int vowelStrings(std::vector<std::string>& words, int left, int right) {
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };
        int ans = 0;
        for (int i = left; i <= right; ++i) {
            const auto& w = words[i];
            if (isVowel(w.front()) && isVowel(w.back())) {
                ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int vowelStrings(String[] words, int left, int right) {
        String vowels = "aeiou";
        int ans = 0;
        for (int i = left; i <= right; i++) {
            String w = words[i];
            if (vowels.indexOf(w.charAt(0)) != -1 && vowels.indexOf(w.charAt(w.length() - 1)) != -1) {
                ans++;
            }
        }
        return ans;
    }
}

var vowelStrings = function(words, left, right) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    let ans = 0;
    for (let i = left; i <= right; i++) {
        const w = words[i];
        if (vowels.has(w[0]) && vowels.has(w[w.length - 1])) {
            ans++;
        }
    }
    return ans;
};
